<script>
(function(){
"use strict";
var TAU=Math.PI*2, COINH=0.085, Z0=4, TS=512;

/* ---------------- lights (world space, fixed) ---------------- */
function nrm(x,y,z){var l=1/Math.sqrt(x*x+y*y+z*z);return[x*l,y*l,z*l];}
var L1=nrm(-0.50,0.62,0.62), H1=nrm(L1[0],L1[1],L1[2]+1);
var L2=nrm(0.65,-0.35,0.45), H2=nrm(L2[0],L2[1],L2[2]+1);

/* ---------------- materials ---------------- */
function mat(r,g,b,ks,shin,st){
  st=(st===undefined)?0.55:st;
  return{r:r,g:g,b:b,ks:ks,shin:shin,
    sr:r+(1-r)*st, sg:g+(1-g)*st, sb:b+(1-b)*st};
}
var MAT_HERO  =mat(0.85,0.63,0.29,1.15,110);
var MAT_BRONZE=mat(0.55,0.34,0.20,0.90,70);
var MAT_SILVER=mat(0.72,0.74,0.78,1.25,130);
var MAT_GOLD  =mat(0.88,0.65,0.27,1.25,120);
var MAT_BLACK =mat(0.085,0.085,0.115,1.75,210,0.9);

/* ---------------- face textures (procedural height -> normals) ------- */
function arcText(c,text,cx,cy,r,font,bottom){
  c.font=font;c.textAlign="center";c.textBaseline="middle";
  var i,w,widths=[],total=0;
  for(i=0;i<text.length;i++){w=c.measureText(text[i]).width;widths.push(w);total+=w;}
  var ang=-(total/2)/r;
  for(i=0;i<text.length;i++){
    w=widths[i];ang+=w/(2*r);
    c.save();
    if(!bottom){c.translate(cx+r*Math.sin(ang),cy-r*Math.cos(ang));c.rotate(ang);}
    else{c.translate(cx+r*Math.sin(ang),cy+r*Math.cos(ang));c.rotate(-ang);}
    c.fillText(text[i],0,0);c.restore();
    ang+=w/(2*r);
  }
}
function blurAxis(src,S,horiz){
  var out=new Float32Array(src.length),x,y,k,s,idx;
  for(y=0;y<S;y++)for(x=0;x<S;x++){
    s=0;
    for(k=-2;k<=2;k++){
      if(horiz){idx=y*S+Math.min(S-1,Math.max(0,x+k));}
      else{idx=Math.min(S-1,Math.max(0,y+k))*S+x;}
      s+=src[idx];
    }
    out[y*S+x]=s/5;
  }
  return out;
}
function makeTexture(draw){
  var cv=document.createElement("canvas");cv.width=cv.height=TS;
  var c=cv.getContext("2d");
  c.fillStyle="#000";c.fillRect(0,0,TS,TS);
  draw(c);
  var d=c.getImageData(0,0,TS,TS).data,n=TS*TS,i;
  var h=new Float32Array(n);
  for(i=0;i<n;i++)h[i]=(d[i*4]*0.299+d[i*4+1]*0.587+d[i*4+2]*0.114)/255;
  h=blurAxis(h,TS,true);h=blurAxis(h,TS,false);
  var gx=new Float32Array(n),gy=new Float32Array(n),am=new Float32Array(n);
  var STR=3.5,x,y,p;
  for(y=0;y<TS;y++)for(x=0;x<TS;x++){
    p=y*TS+x;
    gx[p]=((x<TS-1?h[p+1]:h[p])-(x>0?h[p-1]:h[p]))*STR;
    gy[p]=((y<TS-1?h[p+TS]:h[p])-(y>0?h[p-TS]:h[p]))*STR;
    am[p]=0.80+0.38*h[p];
  }
  return{gx:gx,gy:gy,am:am};
}
function ring(c,r,w,col){
  c.strokeStyle=col;c.lineWidth=w;
  c.beginPath();c.arc(256,256,r,0,TAU);c.stroke();
}
var texFront=makeTexture(function(c){
  var i,a;
  ring(c,238,15,"#ffffff");                       /* raised rim */
  /* bead ring */
  c.fillStyle="#e0e0e0";
  for(i=0;i<64;i++){a=i/64*TAU;
    c.beginPath();c.arc(256+222*Math.cos(a),256+222*Math.sin(a),4,0,TAU);c.fill();}
  /* legends */
  c.fillStyle="#ededed";
  arcText(c,"WASTEDTOKEN MINT",256,256,192,"700 34px Georgia, serif",false);
  arcText(c,"\u2605 STRUCK BY HAND \u00B7 EST. 2026 \u2605",256,256,192,"700 24px Georgia, serif",true);
  /* sunburst rays behind monogram */
  c.strokeStyle="#8f8f8f";c.lineWidth=3;
  for(i=0;i<28;i++){a=i/28*TAU;
    c.beginPath();
    c.moveTo(256+60*Math.cos(a),256+60*Math.sin(a));
    c.lineTo(256+150*Math.cos(a),256+150*Math.sin(a));
