/* ---------------- frame setup: M = Rx(a) * Ry(b) ---------------- */
function makeFrame(a,b,material){
  var ca=Math.cos(a),sa=Math.sin(a),cb=Math.cos(b),sb=Math.sin(b);
  var m00=cb,      m02=sb,
      m10=sa*sb,   m11=ca, m12=-sa*cb,
      m20=-ca*sb,  m21=sa, m22=ca*cb;
  var dlx=-m20,dly=-m21,dlz=-m22;
  return{m00:m00,m02:m02,m10:m10,m11:m11,m12:m12,m20:m20,m21:m21,m22:m22,
    dlx:dlx,dly:dly,dlz:dlz,
    k0:m20*Z0,k1:m21*Z0,k2:m22*Z0,
    a2:dlx*dlx+dly*dly,mat:material};
}

/* ---------------- ray cast: orthographic ray vs coin cylinder -------- */
function cast(wx,wy,F,out){
  var olx=F.m00*wx+F.m10*wy+F.k0,
      oly=F.m11*wy+F.k1,
      olz=F.m02*wx+F.m12*wy+F.k2,
      dlx=F.dlx,dly=F.dly,dlz=F.dlz;
  var sIn=-1e9,sOut=1e9,t1,t2;
  if(dlz>1e-9||dlz<-1e-9){
    t1=(COINH-olz)/dlz;t2=(-COINH-olz)/dlz;
    if(t1<t2){sIn=t1;sOut=t2;}else{sIn=t2;sOut=t1;}
  }else if(olz>COINH||olz<-COINH)return false;
  var cIn=-1e9,cOut=1e9;
  if(F.a2>1e-9){
    var b2=olx*dlx+oly*dly,c2=olx*olx+oly*oly-1,disc=b2*b2-F.a2*c2;
    if(disc<0)return false;
    var sq=Math.sqrt(disc);
    cIn=(-b2-sq)/F.a2;cOut=(-b2+sq)/F.a2;
  }else if(olx*olx+oly*oly>1)return false;
  var tin=cIn>sIn?cIn:sIn, tout=cOut<sOut?cOut:sOut;
  if(tin>tout)return false;
  var px=olx+dlx*tin, py=oly+dly*tin, pz=olz+dlz*tin;
  var nx,ny,nz,tm;
  if(cIn>sIn){                    /* --- reeded edge --- */
    var ang=Math.atan2(py,px), rd=Math.sin(ang*96);
    nx=px-py*rd*0.8; ny=py+px*rd*0.8;
    var q=pz/COINH; nz=q*q*q*0.5;
    tm=0.72+0.26*rd;
  }else{                          /* --- embossed cap --- */
    var front=pz>0, tex=front?texFront:texBack;
    var u=front?(0.5+px*0.5):(0.5-px*0.5), v=0.5-py*0.5;
    var ix=(u*511.9)|0, iy=(v*511.9)|0;
    if(ix<0)ix=0;else if(ix>511)ix=511;
    if(iy<0)iy=0;else if(iy>511)iy=511;
    var i=(iy<<9)+ix, gx=tex.gx[i], gy=tex.gy[i];
    tm=tex.am[i];
    if(front){nx=-gx+px*0.20;ny=gy+py*0.20;nz=1;}
    else{nx=gx+px*0.20;ny=gy+py*0.20;nz=-1;}
  }
  var il=1/Math.sqrt(nx*nx+ny*ny+nz*nz);nx*=il;ny*=il;nz*=il;
  /* world-space normal */
  var Nx=F.m00*nx+F.m02*nz,
      Ny=F.m10*nx+F.m11*ny+F.m12*nz,
      Nz=F.m20*nx+F.m21*ny+F.m22*nz;
  /* Blinn-Phong metal shading, fixed world lights + env band + fresnel */
  var m=F.mat;
  var d1=Nx*L1[0]+Ny*L1[1]+Nz*L1[2];if(d1<0)d1=0;
  var d2=Nx*L2[0]+Ny*L2[1]+Nz*L2[2];if(d2<0)d2=0;
  var s1=Nx*H1[0]+Ny*H1[1]+Nz*H1[2];if(s1<0)s1=0;
  var s2=Nx*H2[0]+Ny*H2[1]+Nz*H2[2];if(s2<0)s2=0;
  var spec=Math.pow(s1,m.shin)*m.ks+Math.pow(s2,32)*0.22;
  var fr=1-(Nz>0?Nz:0);fr=fr*fr*fr*0.5;
  var ry=2*Nz*Ny;
  var env=1-Math.abs(ry-0.35)*1.7;env=env<0?0:env*env*0.35;
  var lum=(0.26+1.05*d1+0.38*d2)*tm;
  var sp=spec+env*0.6+fr;
  var r=m.r*lum+m.sr*sp, g=m.g*lum+m.sg*sp, b=m.b*lum+m.sb*sp;
  out[0]=Math.sqrt(r>1?1:r)*255;
  out[1]=Math.sqrt(g>1?1:g)*255;
  out[2]=Math.sqrt(b>1?1:b)*255;
  return true;
}

/* ---------------- rasterizer with silhouette anti-aliasing ----------- */
var scratch=[0,0,0];
function renderCoinTo(cv,F,scale,bg){
  var S=cv.width, ctx=cv.getContext("2d");
  var st=cv._rs;
  if(!st)st=cv._rs={img:ctx.createImageData(S,S),mask:new Uint8Array(S*S)};
  var img=st.img,d=img.data,mask=st.mask;
  var c0=S/2, inv=1/scale, lim=1.012*1.012;
  var out=scratch,x,y,p=0,q,wx,wy,hit;
  for(y=0;y<S;y++){
    wy=(c0-y-0.5)*inv;
    for(x=0;x<S;x++,p++){
      wx=(x+0.5-c0)*inv;
      hit=(wx*wx+wy*wy<=lim)&&cast(wx,wy,F,out);
      mask[p]=hit?1:0;
      q=p*4;
      if(hit){d[q]=out[0];d[q+1]=out[1];d[q+2]=out[2];}
      else{d[q]=bg[0];d[q+1]=bg[1];d[q+2]=bg[2];}
      d[q+3]=255;
    }
  }
  /* refine silhouette pixels with 2x2 subsamples */
  var sx,sy,r,g,b,m0;
  for(y=1;y<S-1;y++)for(x=1;x<S-1;x++){
    p=y*S+x;m0=mask[p];
    if(mask[p-1]!==m0||mask[p+1]!==m0||mask[p-S]!==m0||mask[p+S]!==m0){
      r=0;g=0;b=0;
      for(sy=0;sy<2;sy++)for(sx=0;sx<2;sx++){
        wx=(x+0.25+sx*0.5-c0)*inv;
        wy=(c0-y-0.25-sy*0.5)*inv;
        if(cast(wx,wy,F,out)){r+=out[0];g+=out[1];b+=out[2];}
        else{r+=bg[0];g+=bg[1];b+=bg[2];}
      }
      q=p*4;d[q]=r/4;d[q+1]=g/4;d[q+2]=b/4;
    }
  }
  ctx.putImageData(img,0,0);
}

